  for(const u of actual){const producer=byId.get(u.phaseId);assert(producer,'Selected upstream producer missing');const role=u.phaseId==='frontend-image'&&['status-browser','product-browser'].includes(p.phaseId)?'frontend-dist':u.phaseId;assert.equal(u.role,role);const evidence=role===u.phaseId?producer:roleProofs.find(v=>v.role===role);assert(evidence,'Official extra artifact role missing');assert.equal(typeof u.artifactId,'string');assert.equal(typeof u.runId,'string');assert(Number.isSafeInteger(u.producerAttempt));assert.equal(positiveId(u.artifactId),evidence.official.artifactId);assert.equal(positiveId(u.runId),producer.official.runId);assert.equal(positiveId(u.producerAttempt),producer.official.attempt);assert.equal(u.proofSHA256,producer.proofSHA256,'Consumer used a different producer proof');assert.equal(u.artifactDigest,'sha256:'+evidence.official.zipSHA256);assert.equal(u.inputsSHA256,producer.inputsSHA256);}
