const AGGREGATES=Object.freeze({'qualification-result':{jobName:'pr356-result',caseIds:['complete-selected-qualification']},'merge-admission-precheck':{jobName:'pr356-admission',caseIds:['official-qualification-and-ready-source']},'merge-admission':{jobName:'merge gate / ready PR',caseIds:['stable-required-merge-admission']},'main-reuse':{jobName:'pr356-postmerge',caseIds:['exact-main-qualified-artifact-reuse']}});
