async function metadataClient(token,fetcher=fetch){
 assert(typeof token==='string'&&token.length,'Existing official read token missing');return async path=>{const r=await fetcher('https://api.github.com/repos/'+REPOSITORY+'/'+path,{headers:{Authorization:'Bearer '+token,Accept:'application/vnd.github+json','X-GitHub-Api-Version':'2022-11-28'},redirect:'error'});assert.equal(r.status,200,'Official metadata unavailable (no retry/fallback): '+path);return r.json();};
}
