 const artifactExpected=expectedFromOfficialOrigin(role,spec,{kind:'pr356-explicit-official-origin',runId:expected.runId,sourceHead,producerAttempt:expected.attempt,jobId:expected.jobId,artifactId:expected.artifactId,artifactName:expected.artifactName,artifactDigest:'sha256:'+expected.zipSHA256});
