function pinFrom(job,a){assert.match(a.digest??'',/^sha256:[a-f0-9]{64}$/,'Official ZIP digest unavailable');return {runId:positiveId(job.run_id),attempt:positiveId(job.run_attempt),jobId:positiveId(job.id),artifactId:positiveId(a.id),artifactName:a.name,sourceHead:job.head_sha,zipSHA256:a.digest.slice(7),zipBytes:a.size_in_bytes};}
