 assert.equal((body.match(/<!-- pr356-admission-pin:/g)||[]).length,1,'Ambiguous PR admission pin marker');
 const matches=[...body.matchAll(/<!-- pr356-admission-pin:v1\s+([\s\S]*?)\s+-->/g)];
 assert.equal(matches.length,1,'Exactly one explicit PR admission pin required');
